    uint8_t inb[MAX_FRAME];
    uint8_t mac_host[4][6], mac_sw[4][6];
    uint32_t ip_host[4], ip_sw[4];
};

typedef struct collector collector_t;

static int rank_of_ordinal(int dest, int ordinal) {
    for (int r = 0; r < 4; r++) {
        if (r == dest) {
            continue;
        }
        if (ordinal == 0) {
            return r;
        }
        ordinal--;
    }
    return 0;
}

static int ordinal_of(int dest, int src) {
    int ordinal = 0;
    for (int r = 0; r < 4; r++) {
        if (r == dest) {
            continue;
        }
        if (r == src) {
            return ordinal;
        }
        ordinal++;
    }
    return 0;
}

static bool is_source(const collector_t *c, int rank) {
    return c->primitive != P_BCAST || rank == c->root;
}

static uint32_t out_limit(const collector_t *c, int d) {
    switch (c->primitive) {
    case P_ALLREDUCE:
        return c->K;
    case P_REDUCE:
        return d == c->root ? c->K : 0;
    case P_BCAST:
        return d == c->root ? 0 : c->K;
    case P_BARRIER:
        return 1;
    case P_ALLGATHER:
        return 3u * c->K;
    case P_RSCATTER:
        return c->quarter;
    }
    return 0;
}

/* Map a destination output position q to its input p and payload source. */
static bool output_map(const collector_t *c, int d, uint32_t q, uint32_t *pp, int *srcp) {
    uint32_t p = 0;
    int src = -1;
    switch (c->primitive) {
    case P_ALLREDUCE:
        p = q;
        break;
    case P_REDUCE:
        if (d != c->root) {
            return false;
        }
        p = q;
        break;
    case P_BCAST:
        if (d == c->root) {
            return false;
        }
        p = q;
        break;
    case P_BARRIER:
        if (q != 0) {
            return false;
        }
        p = 0;
        break;
    case P_ALLGATHER:
        p = q / 3u;
        src = rank_of_ordinal(d, (int)(q % 3u));
        break;
    case P_RSCATTER:
        p = (uint32_t)d * c->quarter + q;
        break;
    default:
        return false;
    }
    if (p >= c->K) {
        return false;
    }
    *pp = p;
    *srcp = src;
    return true;
}

static slot_t *slot_of(const collector_t *c, uint32_t p) {
    slot_t *s = &c->slots[p % c->N];
    if (!s->in_use || s->p != p) {
        return NULL;
    }
    return s;
}

static bool output_ready(collector_t *c, int d, uint32_t q) {
    uint32_t p;
    int src;
    if (!output_map(c, d, q, &p, &src)) {
        return false;
    }
    slot_t *s = slot_of(c, p);
    return s && s->complete;
}

static uint8_t *slot_payload(collector_t *c, uint32_t p) {
    return c->pay + (size_t)(p % c->N) * c->stride;
}

/* ------------------------------ transcript ------------------------------ */

static bool emit_frame(collector_t *c, int rank, const uint8_t *frame, size_t len, bool ack) {
    if (c->budget == 0) {
        c->n_failed++;
        return false;
    }
    if (c->budget > 0) {
        c->budget--;
    }
    uint8_t head[5];
    head[0] = (uint8_t)rank;
    head[1] = (uint8_t)(len & 0xffu);
    head[2] = (uint8_t)((len >> 8) & 0xffu);
    head[3] = (uint8_t)((len >> 16) & 0xffu);
    head[4] = (uint8_t)((len >> 24) & 0xffu);
    sha_update(&c->sha, head, 5);
    sha_update(&c->sha, frame, len);
    c->packets++;
    c->bytes += (uint64_t)len;
    if (ack) {
        c->n_tx_ack++;
    } else {
        c->n_tx_data++;
    }
    if (c->trace_count < c->trace_limit) {
        epic_trace_t *t = &c->trace[c->trace_count++];
        t->len = (uint32_t)len;
        t->rank = (uint8_t)rank;
        memcpy(t->frame, frame, len);
    }
    return true;
}

static bool send_ack_to(collector_t *c, int rank, uint32_t prefix) {
    const epic_port_t dummy;
    (void)dummy;
    size_t len = epic_build_roce_ack(c->out, sizeof(c->out), c->mac_sw[rank], c->mac_host[rank],
                                     c->ip_sw[rank], c->ip_host[rank], EPIC_ROCE_UDP_PORT,
                                     EPIC_ROCE_UDP_PORT, 0x100u + (uint32_t)rank,
                                     (c->start + prefix - 1u) & M24);
    if (!len) {
        return false;
    }
    return emit_frame(c, rank, c->out, len, true);
}

static bool send_output(collector_t *c, int d, uint32_t q) {
    uint32_t p;
    int src;
    if (!output_map(c, d, q, &p, &src)) {
        return false;
    }
    slot_t *s = slot_of(c, p);
    if (!s) {
        return false;
    }
    uint32_t psn = (c->start + q) & M24;
    size_t len;
    if (c->primitive == P_ALLGATHER) {
        if (!s->g[src]) {
            return false;
        }
        len = epic_build_roce_data_raw(c->out, sizeof(c->out), c->mac_sw[d], c->mac_host[d],
                                       c->ip_sw[d], c->ip_host[d], EPIC_ROCE_UDP_PORT,
                                       EPIC_ROCE_UDP_PORT, 0x100u + (uint32_t)d, psn, s->g[src],
                                       c->plen);
    } else if (c->primitive == P_BCAST) {
        len = epic_build_roce_data_raw(c->out, sizeof(c->out), c->mac_sw[d], c->mac_host[d],
                                       c->ip_sw[d], c->ip_host[d], EPIC_ROCE_UDP_PORT,
                                       EPIC_ROCE_UDP_PORT, 0x100u + (uint32_t)d, psn,
                                       slot_payload(c, p), c->plen);
    } else {
        len = epic_build_roce_data(c->out, sizeof(c->out), c->mac_sw[d], c->mac_host[d],
                                   c->ip_sw[d], c->ip_host[d], EPIC_ROCE_UDP_PORT,
                                   EPIC_ROCE_UDP_PORT, 0x100u + (uint32_t)d, psn,
                                   (const int32_t *)slot_payload(c, p), c->plen);
    }
    if (!len) {
        return false;
    }
    return emit_frame(c, d, c->out, len, false);
}

/* ------------------------- eligibility and safety ------------------------- */

static bool contribution_safe(const collector_t *c, int r, uint32_t p) {
    if (c->mode == MODE_OWN) {
        return true;
    }
    switch (c->primitive) {
    case P_ALLREDUCE:
    case P_BARRIER:
        return c->acked[r] > p;
    case P_REDUCE:
        return c->acked[c->root] > p;
    case P_BCAST:
        for (int d = 0; d < 4; d++) {
            if (d == c->root) {
                continue;
            }
            if (c->acked[d] <= p) {
                return false;
            }
        }
        return true;
    case P_RSCATTER:
        return c->acked[p / c->quarter] > p % c->quarter;
    case P_ALLGATHER:
        for (int d = 0; d < 4; d++) {
            if (d == r) {
                continue;
            }
            if (c->acked[d] <= 3u * p + (uint32_t)ordinal_of(d, r)) {
                return false;
            }
        }
        return true;
    }
    return false;
}

static void extend_eligible(collector_t *c, int r) {
    if (c->mode == MODE_OWN) {
        c->E[r] = c->R[r];
        return;
    }
    while (c->E[r] < c->R[r] && contribution_safe(c, r, c->E[r])) {
        c->E[r]++;
    }
}

static bool outputs_acked(const collector_t *c, uint32_t p) {
    switch (c->primitive) {
    case P_ALLREDUCE:
        for (int d = 0; d < 4; d++) {
            if (c->acked[d] <= p) {
                return false;
            }
        }
        return true;
    case P_REDUCE:
        return c->acked[c->root] > p;
    case P_BCAST:
        for (int d = 0; d < 4; d++) {
            if (d == c->root) {
                continue;
            }
            if (c->acked[d] <= p) {
                return false;
            }
        }
        return true;
    case P_BARRIER:
        for (int d = 0; d < 4; d++) {
            if (c->acked[d] < 1u) {
                return false;
            }
        }
        return true;
    case P_ALLGATHER:
        for (int d = 0; d < 4; d++) {
            if (c->acked[d] < 3u * p + 3u) {
                return false;
            }
        }
        return true;
    case P_RSCATTER:
        return c->acked[p / c->quarter] > p % c->quarter;
    }
    return false;
}

static bool upstream_sent(const collector_t *c, uint32_t p) {
    for (int r = 0; r < 4; r++) {
        if (!is_source(c, r)) {
            continue;
        }
        if (c->U[r] <= p) {
            return false;
        }
    }
    return true;
}

static void free_slot(collector_t *c, slot_t *s) {
    for (int r = 0; r < 4; r++) {
        free(s->g[r]);
        s->g[r] = NULL;
    }
    if (s->in_use) {
        c->occupied--;
    }
    memset(s, 0, sizeof(*s));
    s->p = 0;
    s->in_use = 0;
}

static void retire(collector_t *c) {
    for (;;) {
        if (c->b >= c->K) {
            return;
        }
        uint32_t p = c->b;
        slot_t *s = slot_of(c, p);
        if (!s || !s->complete) {
            return;
        }
        if (!outputs_acked(c, p) || !upstream_sent(c, p)) {
            return;
        }
        free_slot(c, s);
        c->b++;
    }
}

/* ------------------------------- service ------------------------------- */

static void service(collector_t *c, bool is_retry, int retry_rank) {
    for (int r = 0; r < 4; r++) {
        extend_eligible(c, r);
    }

    /* 1. eligible pending upstream ACKs, ascending rank */
    for (int r = 0; r < 4; r++) {
        if (c->E[r] == 0 || (!c->repeat[r] && c->E[r] <= c->U[r])) {
            continue;
        }
        if (!send_ack_to(c, r, c->E[r])) {
            retire(c);
            return;
        }
        c->U[r] = c->E[r];
        c->repeat[r] = 0;
    }

    /* 2. on retry only: the selected receiver's sent but unacknowledged results */
    if (is_retry) {
        uint32_t q = c->acked[retry_rank];
        while (q < c->S[retry_rank]) {
            if (!output_ready(c, retry_rank, q)) {
                break;
            }
            if (!send_output(c, retry_rank, q)) {
                retire(c);
                return;
            }
            q++;
        }
    }

    /* 3. new results, ascending destination rank then q */
    for (int d = 0; d < 4; d++) {
        while (c->S[d] < out_limit(c, d)) {
            if (!output_ready(c, d, c->S[d])) {
                break;
            }
            if (!send_output(c, d, c->S[d])) {
                retire(c);
                return;
            }
            c->S[d]++;
        }
    }
    retire(c);
}

/* --------------------------- wire classification --------------------------- */

static bool wire_valid(const collector_t *c, const uint8_t *f, size_t len, rx_info_t *info) {
    if (len < 58u) {
        return false;
    }
    if (f[12] != 0x08 || f[13] != 0x00) {
        return false;
    }
    const uint8_t *ip = f + 14;
    size_t ip_len = ((size_t)ip[2] << 8) | (size_t)ip[3];
    if (ip_len + 14u != len) {
        return false;
    }
    if (ip[0] != 0x45) {
        return false;
    }
    if (ip[9] != 17) {
        return false;
    }
    uint32_t sum = 0;
    for (int i = 0; i < 20; i += 2) {
        sum += ((uint32_t)ip[i] << 8) | (uint32_t)ip[i + 1];
    }
    while (sum >> 16) {
        sum = (sum & 0xffffu) + (sum >> 16);
    }
    if ((sum & 0xffffu) != 0xffffu) {
        return false;
    }
    uint32_t flags = ((uint32_t)ip[6] << 8) | (uint32_t)ip[7];
    if (flags != 0x0000u && flags != 0x4000u) {
        return false;
    }
    const uint8_t *udp = ip + 20;
    size_t udp_len = ((size_t)udp[4] << 8) | (size_t)udp[5];
    if (udp_len != ip_len - 20u || udp_len < 24u) {
        return false;
    }
    if (udp[0] != 0x12 || udp[1] != 0xb7 || udp[2] != 0x12 || udp[3] != 0xb7) {
        return false;
    }
    if (udp[6] != 0 || udp[7] != 0) {
        return false;
    }
    const uint8_t *bth = udp + 8;
    if (bth[1] != 0 || bth[2] != 0xff || bth[3] != 0xff || bth[4] != 0) {
        return false;
    }
    uint32_t psn = ((uint32_t)bth[9] << 16) | ((uint32_t)bth[10] << 8) | (uint32_t)bth[11];
    uint8_t opcode = bth[0];
    info->is_data = false;
    info->is_ack = false;
    info->payload = NULL;
    if (opcode == 0x04) {
        if (bth[8] != 0x80) {
            return false;
        }
        if (udp_len != 24u + c->plen) {
            return false;
        }
        info->is_data = true;
        info->payload = bth + 12;
    } else if (opcode == 0x11) {
        if (bth[8] != 0x00 || udp_len != 28u) {
            return false;
        }
        if (bth[12] != 0x1f) {
            return false;
        }
        uint32_t msn = ((uint32_t)bth[13] << 16) | ((uint32_t)bth[14] << 8) | (uint32_t)bth[15];
        if (msn != ((psn + 1u) & M24)) {
            return false;
        }
        info->is_ack = true;
    } else {
        return false;
    }
    uint32_t icrc = epic_compute_icrc(f, len);
    const uint8_t *tail = f + len - 4;
    uint32_t stored = (uint32_t)tail[0] | ((uint32_t)tail[1] << 8) | ((uint32_t)tail[2] << 16) |
                      ((uint32_t)tail[3] << 24);
    if (icrc != stored) {
        return false;
    }
    info->psn = psn;
    info->p = (psn - c->start) & M24;
    return true;
}

static bool endpoint_valid(const collector_t *c, int rank, const uint8_t *f, const rx_info_t *info) {
    const uint8_t *dmac = f, *smac = f + 6;
    if (dmac[0] != 0x02 || dmac[1] != 0x01 || dmac[2] != 0 || dmac[3] != 0 || dmac[4] != 0 ||
        dmac[5] != (uint8_t)(rank + 1)) {
        return false;
    }
    if (smac[0] != 0x02 || smac[1] != 0x00 || smac[2] != 0 || smac[3] != 0 || smac[4] != 0 ||
        smac[5] != (uint8_t)(rank + 1)) {
        return false;
    }
    if (memcmp(f + 26, &c->ip_host[rank], 4) != 0) {
        return false;
    }
    if (memcmp(f + 30, &c->ip_sw[rank], 4) != 0) {
        return false;
    }
    const uint8_t *bth = f + 14 + 20 + 8;
    uint32_t qpn = ((uint32_t)bth[5] << 16) | ((uint32_t)bth[6] << 8) | (uint32_t)bth[7];
    if (qpn != 0x200u + (uint32_t)rank) {
        return false;
    }
    if (info->is_data) {
        if (!is_source(c, rank)) {
            return false;
        }
        if (info->p >= c->K) {
            return false;
        }
    }
    return true;
}

/* ------------------------------ ingress ------------------------------ */

static void handle_data(collector_t *c, int rank, const rx_info_t *info) {
    uint32_t p = info->p;
    if (p < c->b) {
        c->n_stale++;
        c->repeat[rank] = 1;
        return;
    }
    if (p >= c->b + c->N) {
        c->n_blocked++;
        return;
    }
    uint32_t idx = p % c->N;
    slot_t *s = &c->slots[idx];
    if (!s->in_use) {
        memset(s, 0, sizeof(*s));
        s->p = p;
        s->in_use = 1;
        c->occupied++;
    }
    uint8_t bit = (uint8_t)(1u << rank);
    if (s->mask & bit) {
        c->n_dup++;
        c->repeat[rank] = 1;
        return;
    }
    if (c->primitive == P_ALLGATHER) {
        uint8_t *copy = malloc(c->plen);
        if (!copy) {
            return;
        }
        memcpy(copy, info->payload, c->plen);
        s->g[rank] = copy;
    } else if (c->primitive == P_BCAST) {
        memcpy(slot_payload(c, p), info->payload, c->plen);
    } else {
        uint32_t *accum = (uint32_t *)slot_payload(c, p);
        const uint8_t *raw = info->payload;
        if (s->mask == 0) {
            for (uint32_t j = 0; j < c->D; j++) {
                accum[j] = ((uint32_t)raw[4 * j] << 24) | ((uint32_t)raw[4 * j + 1] << 16) |
                           ((uint32_t)raw[4 * j + 2] << 8) | (uint32_t)raw[4 * j + 3];
            }
        } else {
            for (uint32_t j = 0; j < c->D; j++) {
                uint32_t v = ((uint32_t)raw[4 * j] << 24) | ((uint32_t)raw[4 * j + 1] << 16) |
                             ((uint32_t)raw[4 * j + 2] << 8) | (uint32_t)raw[4 * j + 3];
                accum[j] += v;
            }
        }
    }
    s->mask |= bit;
    s->complete = (s->mask == c->need_mask) ? 1u : 0u;
    c->n_accepted++;
    if (p == c->R[rank]) {
        while (c->R[rank] < c->K) {
            slot_t *t = slot_of(c, c->R[rank]);
            if (!t || !(t->mask & bit)) {
                break;
            }
            c->R[rank]++;
        }
    }
}

static void handle_ack(collector_t *c, int rank, const rx_info_t *info) {
    uint32_t prefix = (info->psn - c->start + 1u) & M24;
    if (prefix > c->acked[rank] && prefix <= c->S[rank]) {
        c->acked[rank] = prefix;
    } else {
        c->n_ack_ignored++;
    }
}

static void ingress_frame(collector_t *c, int rank, const uint8_t *frame, size_t len) {
    rx_info_t info;
    if (!wire_valid(c, frame, len, &info)) {
        c->n_wire++;
        return;
    }
    if (!endpoint_valid(c, rank, frame, &info)) {
        c->n_endpoint++;
        return;
    }
    if (info.is_ack) {
        c->n_rx_ack++;
        handle_ack(c, rank, &info);
    } else {
        c->n_rx_data++;
        handle_data(c, rank, &info);
    }
    service(c, false, -1);
}

/* ------------------------------ generated wire ------------------------------ */

static void build_payload_words(const collector_t *c, uint32_t seed, uint32_t p, int rank,
                                uint8_t *dst) {
    for (uint32_t j = 0; j < c->D; j++) {
        uint32_t v = seed + 0x9e3779b9u * (p + 1u) + 0x85ebca6bu * (uint32_t)(rank + 1) +
                     0xc2b2ae35u * (j + 1u);
        dst[4 * j] = (uint8_t)(v >> 24);
        dst[4 * j + 1] = (uint8_t)(v >> 16);
        dst[4 * j + 2] = (uint8_t)(v >> 8);
        dst[4 * j + 3] = (uint8_t)v;
    }
}

static void emit_generated_data(collector_t *c, int rank, uint32_t p, uint32_t seed,
                                const uint32_t *values, const int32_t *xors, int32_t nxor) {
    size_t len = epic_build_roce_data_raw(c->inb, sizeof(c->inb), c->mac_host[rank], c->mac_sw[rank],
                                          c->ip_host[rank], c->ip_sw[rank], EPIC_ROCE_UDP_PORT,
                                          EPIC_ROCE_UDP_PORT, 0x200u + (uint32_t)rank,
                                          (c->start + p) & M24, c->out, c->plen);
    if (!len) {
        return;
    }
    /* epic_build_roce_data_raw copies c->out, so stage the payload there first. */
    (void)values;
    (void)seed;
    (void)rank;
    (void)p;
    for (int32_t i = 0; i < nxor; i++) {
        int32_t off = xors[2 * i];
        int32_t val = xors[2 * i + 1];
        if (off >= 0 && (size_t)off < len) {
            c->inb[off] ^= (uint8_t)val;
        }
    }
    ingress_frame(c, rank, c->inb, len);
}

/* ------------------------------ certificates ------------------------------ */

static uint64_t fnv_byte(uint64_t h, uint8_t v) {
    return (h ^ (uint64_t)v) * UINT64_C(1099511628211);
}

static uint64_t fnv_word(uint64_t h, uint32_t v) {
    h = fnv_byte(h, (uint8_t)v);
    v >>= 8;
    h = fnv_byte(h, (uint8_t)v);
    v >>= 8;
    h = fnv_byte(h, (uint8_t)v);
    v >>= 8;
    return fnv_byte(h, (uint8_t)v);
}

static uint64_t fnv_u64(uint64_t h, uint64_t v) {
    for (int i = 0; i < 8; i++) {
        h = fnv_byte(h, (uint8_t)v);
        v >>= 8;
    }
    return h;
}

static uint64_t buffer_digest(const collector_t *c) {
    uint64_t h = UINT64_C(14695981039346656037);
    uint32_t end = c->b + c->N;
    if (end > c->K) {
        end = c->K;
    }
    for (uint32_t p = c->b; p < end; p++) {
        slot_t *s = slot_of(c, p);
        if (!s) {
            continue;
        }
        h = fnv_u64(h, p);
        h = fnv_byte(h, s->mask);
        h = fnv_byte(h, s->complete);
        if (c->primitive == P_ALLGATHER) {
            for (int r = 0; r < 4; r++) {
                h = fnv_byte(h, s->g[r] != NULL);
                if (s->g[r]) {
                    const uint8_t *raw = s->g[r];
                    for (size_t j = 0; j < c->plen; j++) {
                        h = fnv_byte(h, raw[j]);
                    }
                }
            }
        } else if (c->plen) {
            if (c->primitive == P_BCAST) {
                const uint8_t *raw = slot_payload(c, p);
                for (size_t j = 0; j < c->plen; j++) {
                    h = fnv_byte(h, raw[j]);
                }
            } else {
                const uint32_t *accum = (const uint32_t *)slot_payload(c, p);
                for (uint32_t j = 0; j < c->D; j++) {
                    h = fnv_word(h, accum[j]);
                }
            }
        }
    }
    return h;
}

static void fill_state(collector_t *c, uint64_t *state) {
    memset(state, 0, 32 * sizeof(*state));
    state[0] = c->b;
    state[1] = c->occupied;
    for (int r = 0; r < 4; r++) {
        state[2 + r] = c->R[r];
        state[6 + r] = c->S[r];
        state[10 + r] = c->acked[r];
        state[14 + r] = c->U[r];
    }
    state[18] = c->n_rx_data;
    state[19] = c->n_rx_ack;
    state[20] = c->n_tx_data;
    state[21] = c->n_tx_ack;
    state[22] = c->n_accepted;
    state[23] = c->n_dup;
    state[24] = c->n_blocked;
    state[25] = c->n_stale;
    state[26] = c->n_wire;
    state[27] = c->n_endpoint;
    state[28] = c->n_ack_ignored;
    state[29] = c->n_failed;
    state[30] = c->n_overwrite;
    state[31] = 0;
}

static void record_snapshot(collector_t *c) {
    if (c->snap_count == c->snap_cap) {
        uint32_t cap = c->snap_cap ? c->snap_cap * 2u : 16u;
        epic_snap_t *grow = realloc(c->snaps, (size_t)cap * sizeof(epic_snap_t));
        if (!grow) {
            return;
        }
        c->snaps = grow;
        c->snap_cap = cap;
    }
    epic_snap_t *snap = &c->snaps[c->snap_count++];
    fill_state(c, snap->state);
    snap->buffer = buffer_digest(c);
    sha_final(&c->sha, snap->sha);
    snap->packets = c->packets;
    snap->bytes = c->bytes;
}

/* ------------------------------ event runner ------------------------------ */

static void run_train(collector_t *c, const epic_event_t *ev) {
    uint32_t lo = (uint32_t)ev->p;
    uint32_t end = lo + (uint32_t)ev->count;
    for (; lo < end; lo += (uint32_t)ev->width) {
        uint32_t hi = (lo + (uint32_t)ev->width < end) ? lo + (uint32_t)ev->width : end;
        for (int i = 0; i < 4; i++) {
            int r = ev->ranks[i];
            if (c->primitive == P_BCAST && r != c->root) {
                continue;
            }
            if (ev->reverse) {
                for (uint32_t p = hi; p-- > lo;) {
                    build_payload_words(c, ev->seed, p, r, c->out);
                    emit_generated_data(c, r, p, ev->seed, NULL, ev->xors, 0);
                }
            } else {
                for (uint32_t p = lo; p < hi; p++) {
                    build_payload_words(c, ev->seed, p, r, c->out);
                    emit_generated_data(c, r, p, ev->seed, NULL, ev->xors, 0);
                }
            }
        }
        for (int r = 0; r < 4; r++) {
            uint32_t n;
            if (c->primitive == P_ALLGATHER) {
                n = 3u * hi;
            } else if (c->primitive == P_RSCATTER) {
                int64_t v = (int64_t)hi - (int64_t)r * (int64_t)c->quarter;
                n = (v <= 0) ? 0u : ((uint64_t)v >= (uint64_t)c->quarter ? c->quarter : (uint32_t)v);
            } else {
                bool receiver = (c->primitive != P_REDUCE || r == c->root) &&
                                (c->primitive != P_BCAST || r != c->root);
                n = receiver ? hi : 0u;
            }
            size_t len = epic_build_roce_ack(c->inb, sizeof(c->inb), c->mac_host[r], c->mac_sw[r],
                                             c->ip_host[r], c->ip_sw[r], EPIC_ROCE_UDP_PORT,
                                             EPIC_ROCE_UDP_PORT, 0x200u + (uint32_t)r,
                                             (c->start + n - 1u) & M24);
            if (!len) {
                continue;
            }
            ingress_frame(c, r, c->inb, len);
        }
    }
}

void epic_run(void *context, const epic_event_t *events, int32_t count) {
    collector_t *c = (collector_t *)context;
    if (!c) {
        return;
    }
    for (int32_t i = 0; i < count; i++) {
        const epic_event_t *ev = &events[i];
        switch (ev->op) {
        case EPIC_EV_DATA: {
            int rank = ev->rank;
            for (int32_t k = 0; k < ev->count; k++) {
                uint32_t p = (uint32_t)(ev->p + k * ev->step);
                if (ev->values) {
                    for (uint32_t j = 0; j < c->D; j++) {
                        uint32_t v = ev->values[j];
                        c->out[4 * j] = (uint8_t)(v >> 24);
                        c->out[4 * j + 1] = (uint8_t)(v >> 16);
                        c->out[4 * j + 2] = (uint8_t)(v >> 8);
                        c->out[4 * j + 3] = (uint8_t)v;
                    }
                } else {
                    build_payload_words(c, ev->seed, p, rank, c->out);
                }
                size_t len = epic_build_roce_data_raw(c->inb, sizeof(c->inb), c->mac_host[rank],
                                                      c->mac_sw[rank], c->ip_host[rank],
                                                      c->ip_sw[rank], EPIC_ROCE_UDP_PORT,
                                                      EPIC_ROCE_UDP_PORT, 0x200u + (uint32_t)rank,
                                                      (c->start + p) & M24, c->out, c->plen);
                if (!len) {
                    continue;
                }
                for (int32_t x = 0; x < ev->nxor; x++) {
                    int32_t off = ev->xors[2 * x];
                    int32_t val = ev->xors[2 * x + 1];
                    if (off >= 0 && (size_t)off < len) {
                        c->inb[off] ^= (uint8_t)val;
                    }
                }
                ingress_frame(c, rank, c->inb, len);
            }
            break;
        }
        case EPIC_EV_ACK: {
            int rank = ev->rank;
            uint32_t upto = (uint32_t)ev->upto;
            size_t len = epic_build_roce_ack(c->inb, sizeof(c->inb), c->mac_host[rank],
                                             c->mac_sw[rank], c->ip_host[rank], c->ip_sw[rank],
                                             EPIC_ROCE_UDP_PORT, EPIC_ROCE_UDP_PORT,
                                             0x200u + (uint32_t)rank, (c->start + upto - 1u) & M24);
            if (len) {
                ingress_frame(c, rank, c->inb, len);
            }
            break;
        }
        case EPIC_EV_WIRE:
            ingress_frame(c, ev->rank, ev->wire, (size_t)ev->wire_len);
            break;
        case EPIC_EV_BUDGET:
            c->budget = (int64_t)ev->n;
            break;
        case EPIC_EV_FLUSH:
            service(c, false, -1);
            break;
        case EPIC_EV_RETRY:
            c->repeat[ev->rank] = 1;
            service(c, true, ev->rank);
            break;
        case EPIC_EV_SNAP:
            record_snapshot(c);
            break;
        case EPIC_EV_TRAIN:
            run_train(c, ev);
            break;
        default:
            break;
        }
    }
}

/* ------------------------------ ABI ------------------------------ */

void *epic_open(int primitive, int mode, int root, uint32_t segments, uint32_t words,
                uint32_t capacity, uint32_t start, uint32_t trace) {
    collector_t *c = calloc(1, sizeof(*c));
    if (!c) {
        return NULL;
    }
    c->primitive = primitive;
    c->mode = mode;
    c->root = root;
    c->K = segments;
    c->D = words;
    c->N = capacity;
    c->start = start;
    c->quarter = (primitive == P_RSCATTER) ? segments / 4u : 0u;
    c->need_mask = (primitive == P_BCAST) ? (uint8_t)(1u << root) : 0x0fu;
    c->plen = (size_t)words * 4u;
    c->stride = (primitive == P_ALLGATHER) ? 0u : c->plen;
    c->budget = -1;
    c->trace_limit = trace;
    sha_init(&c->sha);
    for (int r = 0; r < 4; r++) {
        c->mac_host[r][0] = 2;
        c->mac_host[r][5] = (uint8_t)(r + 1);
        c->mac_sw[r][0] = 2;
        c->mac_sw[r][1] = 1;
        c->mac_sw[r][5] = (uint8_t)(r + 1);
        c->ip_host[r] = htonl_safe(0x0a000001u + (uint32_t)r);
        c->ip_sw[r] = htonl_safe(0x0a000065u + (uint32_t)r);
    }
    c->slots = calloc((size_t)capacity, sizeof(slot_t));
    if (!c->slots) {
        free(c);
        return NULL;
    }
    if (c->stride) {
        c->pay = calloc((size_t)capacity, c->stride);
        if (!c->pay) {
            free(c->slots);
            free(c);
            return NULL;
        }
    }
    if (c->trace_limit) {
        c->trace = calloc(c->trace_limit, sizeof(epic_trace_t));
        if (!c->trace) {
            free(c->pay);
            free(c->slots);
            free(c);
            return NULL;
        }
    }
    return c;
}

void epic_close(void *context) {
    collector_t *c = (collector_t *)context;
    if (!c) {
        return;
    }
    for (uint32_t i = 0; i < c->N; i++) {
        for (int r = 0; r < 4; r++) {
            free(c->slots[i].g[r]);
        }
    }
    free(c->slots);
    free(c->pay);
    free(c->trace);
    free(c->snaps);
    free(c);
}

void epic_ingress(void *context, int rank, const uint8_t *frame, size_t length) {
    collector_t *c = (collector_t *)context;
    if (!c) {
        return;
    }
    ingress_frame(c, rank, frame, length);
}

void epic_flush(void *context) {
    collector_t *c = (collector_t *)context;
    if (c) {
        service(c, false, -1);
    }
}

void epic_retry(void *context, int rank) {
    collector_t *c = (collector_t *)context;
    if (!c) {
        return;
    }
    if (rank < 0 || rank > 3) {
        return;
    }
    c->repeat[rank] = 1;
    service(c, true, rank);
}

const epic_result_t *epic_result(void *context) {
    collector_t *c = (collector_t *)context;
    if (!c) {
        return NULL;
    }
    fill_state(c, c->res.state);
    c->res.buffer = buffer_digest(c);
    sha_final(&c->sha, c->res.sha);
    c->res.packets = c->packets;
    c->res.bytes = c->bytes;
    c->res.snap_count = c->snap_count;
    c->res.trace_count = c->trace_count;
    c->res.snaps = c->snaps;
    c->res.trace = c->trace;
    return &c->res;
}

uint64_t epic_sizeof_result(void) {
    return (uint64_t)sizeof(epic_result_t);
}
