            self.c['failed'] += 1
            return False
        if self.budget > 0:
            self.budget -= 1
        self.h.update(bytes((rank,)) + struct.pack('<I', len(frame)) + frame)
        self.packets += 1
        self.nbytes += len(frame)
        self.c['tx_ack' if ack else 'tx_data'] += 1
        if len(self.trace_frames) < self.trace:
            self.trace_frames.append({'rank': rank, 'hex': frame.hex()})
        return True

    def send_up_ack(self, rank, prefix):
        frame = wire.packet(rank, (self.start + prefix - 1) & MASK, ack=True)
        return self.emit(rank, frame, True)

    def send_result(self, d, q):
        m = self.out_map(d, q)
        slot = self.slots[m[0]]
        p, src = m
        psn = (self.start + q) & MASK
        if self.pr == 'allgather':
            body = slot['gather'][src]
        elif self.pr == 'broadcast':
            body = slot['raw']
        elif self.pr == 'barrier':
            body = b''
        else:
