        return self.emit(d, frame, False)

    # ---- eligibility -------------------------------------------------------
    def safe(self, r, p):
        if self.mode == 3:
            return True
        if self.pr in ('allreduce', 'barrier'):
            return self.acked[r] > p
        if self.pr == 'reduce':
            return self.acked[self.root] > p
        if self.pr == 'broadcast':
            return all(self.acked[d] > p for d in range(4) if d != self.root)
        if self.pr == 'reducescatter':
            return self.acked[p // (self.K // 4)] > p % (self.K // 4)
        return all(self.acked[d] > 3 * p + ord_of(d, r) for d in range(4) if d != r)

