            return all(self.acked[d] > p for d in range(4))
        if self.pr == 'reduce':
            return self.acked[self.root] > p
        if self.pr == 'broadcast':
            return all(self.acked[d] > p for d in range(4) if d != self.root)
        if self.pr == 'barrier':
            return all(self.acked[d] >= 1 for d in range(4))
        if self.pr == 'allgather':
            return all(self.acked[d] >= 3 * p + 3 for d in range(4))
        return self.acked[p // (self.K // 4)] > p % (self.K // 4)

    def retire(self):
