            else:
                for w in slot['accum']:
                    for i in range(4):
                        h = ((h ^ ((w >> (8 * i)) & 0xff)) * 1099511628211) & 0xffffffffffffffff
        return h

    def state(self):
        st = [0] * 32
        st[0] = self.b
        st[1] = self.occupied
        st[2:6] = self.R
        st[6:10] = self.S
        st[10:14] = self.acked
        st[14:18] = self.U
        st[18] = self.c['rx_data']
        st[19] = self.c['rx_ack']
        st[20] = self.c['tx_data']
        st[21] = self.c['tx_ack']
        st[22] = self.c['accepted']
        st[23] = self.c['dup']
        st[24] = self.c['blocked']
        st[25] = self.c['stale']
        st[26] = self.c['wire']
        st[27] = self.c['endpoint']
        st[28] = self.c['ack_ignored']
        st[29] = self.c['failed']
        st[30] = self.c['overwrite']
        st[31] = 0
        return st

    def snapshot(self):
        return {'state': self.state(), 'buffer': format(self.digest(), '016x'),
                'wire_sha256': self.h.hexdigest(), 'packets': self.packets, 'bytes': self.nbytes}

    # ---- events ------------------------------------------------------------
    def gen_data(self, rank, p, seed=0, values=None, xor=()):
        body = struct.pack('!%dI' % len(values), *values) if values is not None else \
            struct.pack('!%dI' % self.D, *payload_words(seed, p, rank, self.D))
        frame = bytearray(wire.packet(rank, (self.start + p) & MASK, body))
        for offset, byte in xor:
            frame[offset] ^= byte
        self.ingress(rank, bytes(frame))

    def gen_ack(self, rank, upto):
        self.ingress(rank, wire.packet(rank, (self.start + upto - 1) & MASK, ack=True))

    def run_train(self, p, count, width, ranks, reverse=False, seed=0):
        end = p + count
        lo = p
        while lo < end:
            hi = min(end, lo + width)
            for r in ranks:
                if self.pr == 'broadcast' and r != self.root:
                    continue
                seq = range(hi - 1, lo - 1, -1) if reverse else range(lo, hi)
                for pp in seq:
                    self.gen_data(r, pp, seed)
            for r in range(4):
                if self.pr == 'allgather':
                    n = 3 * hi
                elif self.pr == 'reducescatter':
                    n = max(0, min(self.K // 4, hi - r * (self.K // 4)))
                else:
                    recv = (self.pr != 'reduce' or r == self.root) and \
                           (self.pr != 'broadcast' or r != self.root)
                    n = hi if recv else 0
                self.gen_ack(r, n)
            lo += width

    def run(self, events):
        for op in events:
            name = op['op']
            if name == 'data':
                for i in range(op.get('count', 1)):
                    self.gen_data(op['rank'], op['p'] + i * op.get('step', 1), op.get('seed', 0),
                                  op.get('values'), op.get('xor', []))
            elif name == 'ack':
                self.gen_ack(op['rank'], op['upto'])
            elif name == 'wire':
                self.ingress(op['rank'], bytes.fromhex(op['hex']))
            elif name == 'budget':
                self.budget = op['n']
            elif name == 'flush':
                self.service()
            elif name == 'retry':
                self.repeat[op['rank']] = True
                self.service(True, op['rank'])
            elif name == 'snap':
                self.snaps.append(dict(self.snapshot(), tag=op['tag']))
            elif name == 'train':
                self.run_train(op['p'], op['count'], op['width'], op['ranks'],
                               op.get('reverse', False), op.get('seed', 0))
        return self.snapshot()


def solve_case(case):
    ref = Ref(case['primitive'], case['mode'], case['root'], case['segments'], case['words'],
              case['capacity'], case['start'], case.get('trace', 0))
    out = ref.run(case['events'])
    out['snapshots'] = ref.snaps
    out['trace'] = ref.trace_frames
    return out
