/* ============================ collector core ============================ */

enum { P_ALLREDUCE = 0, P_REDUCE = 1, P_BCAST = 2, P_BARRIER = 3, P_ALLGATHER = 4, P_RSCATTER = 5 };
enum { MODE_RELAY = 2, MODE_OWN = 3 };

typedef struct {
    uint32_t p;
    uint8_t in_use, mask, complete;
    uint8_t *g[4];
} slot_t;

typedef struct {
    bool is_data, is_ack;
    uint32_t psn;
    uint32_t p;
    const uint8_t *payload;
} rx_info_t;

struct collector {
    int primitive, mode, root;
    uint32_t K, D, N, start, quarter, need_mask;
    size_t plen, stride;
    uint8_t *pay;
    slot_t *slots;
    uint32_t b;
    uint32_t R[4], E[4], U[4], S[4], acked[4];
    uint8_t repeat[4];
    uint64_t occupied;
    uint64_t n_rx_data, n_rx_ack, n_tx_data, n_tx_ack;
    uint64_t n_accepted, n_dup, n_blocked, n_stale;
    uint64_t n_wire, n_endpoint, n_ack_ignored, n_failed, n_overwrite;
    int64_t budget;
    sha_t sha;
    uint64_t packets, bytes;
    uint32_t trace_limit, trace_count;
    epic_trace_t *trace;
    epic_snap_t *snaps;
    uint32_t snap_count, snap_cap;
    epic_result_t res;
    uint8_t out[MAX_FRAME];
    uint8_t inb[MAX_FRAME];
    uint8_t mac_host[4][6], mac_sw[4][6];
    uint32_t ip_host[4], ip_sw[4];
};

typedef struct collector collector_t;

static int rank_of_ordinal(int dest, int ordinal) {
    for (int r = 0; r < 4; r++) {
        if (r == dest) {
            continue;
        }
        if (ordinal == 0) {
            return r;
        }
        ordinal--;
    }
    return 0;
}

static int ordinal_of(int dest, int src) {
    int ordinal = 0;
    for (int r = 0; r < 4; r++) {
        if (r == dest) {
            continue;
        }
        if (r == src) {
            return ordinal;
        }
        ordinal++;
    }
    return 0;
}

static bool is_source(const collector_t *c, int rank) {
    return c->primitive != P_BCAST || rank == c->root;
}

static uint32_t out_limit(const collector_t *c, int d) {
    switch (c->primitive) {
    case P_ALLREDUCE:
        return c->K;
    case P_REDUCE:
        return d == c->root ? c->K : 0;
    case P_BCAST:
        return d == c->root ? 0 : c->K;
    case P_BARRIER:
        return 1;
    case P_ALLGATHER:
        return 3u * c->K;
    case P_RSCATTER:
        return c->quarter;
    }
    return 0;
}

/* Map a destination output position q to its input p and payload source. */
static bool output_map(const collector_t *c, int d, uint32_t q, uint32_t *pp, int *srcp) {
    uint32_t p = 0;
    int src = -1;
    switch (c->primitive) {
    case P_ALLREDUCE:
        p = q;
        break;
    case P_REDUCE:
        if (d != c->root) {
            return false;
        }
        p = q;
        break;
    case P_BCAST:
        if (d == c->root) {
            return false;
        }
        p = q;
        break;
    case P_BARRIER:
        if (q != 0) {
            return false;
        }
        p = 0;
        break;
    case P_ALLGATHER:
        p = q / 3u;
        src = rank_of_ordinal(d, (int)(q % 3u));
        break;
    case P_RSCATTER:
        p = (uint32_t)d * c->quarter + q;
        break;
    default:
        return false;
    }
    if (p >= c->K) {
        return false;
    }
    *pp = p;
    *srcp = src;
    return true;
}

static slot_t *slot_of(const collector_t *c, uint32_t p) {
    slot_t *s = &c->slots[p % c->N];
    if (!s->in_use || s->p != p) {
        return NULL;
    }
    return s;
}

static bool output_ready(collector_t *c, int d, uint32_t q) {
    uint32_t p;
    int src;
    if (!output_map(c, d, q, &p, &src)) {
        return false;
    }
    slot_t *s = slot_of(c, p);
    return s && s->complete;
}

static uint8_t *slot_payload(const collector_t *c, uint32_t p) {
    return c->pay + (size_t)(p % c->N) * c->stride;
}

/* ------------------------------ transcript ------------------------------ */

static bool emit_frame(collector_t *c, int rank, const uint8_t *frame, size_t len, bool ack) {
    if (c->budget == 0) {
        c->n_failed++;
        return false;
    }
    if (c->budget > 0) {
        c->budget--;
    }
    uint8_t head[5];
    head[0] = (uint8_t)rank;
    head[1] = (uint8_t)(len & 0xffu);

