/* ------------------------------ ingress ------------------------------ */

static void handle_data(collector_t *c, int rank, const rx_info_t *info) {
    uint32_t p = info->p;
    if (p < c->b) {
        c->n_stale++;
        c->repeat[rank] = 1;
        return;
    }
    if (p >= c->b + c->N) {
        c->n_blocked++;
        return;
    }
    uint32_t idx = p % c->N;
    slot_t *s = &c->slots[idx];
    if (s->in_use && s->p != p) {
        c->n_overwrite++;
        free_slot(c, s);
    }
    if (!s->in_use) {
        memset(s, 0, sizeof(*s));
        s->p = p;
        s->in_use = 1;
        c->occupied++;
    }
    uint8_t bit = (uint8_t)(1u << rank);
    if (s->mask & bit) {
        c->n_dup++;
        c->repeat[rank] = 1;
        return;
    }
    uint8_t *copy = NULL;
    if (c->primitive == P_ALLGATHER) {
        copy = malloc(c->plen ? c->plen : 1u);
        if (!copy) {
            return;
        }
        memcpy(copy, info->payload, c->plen);
        s->g[rank] = copy;
    } else if (c->primitive == P_BCAST) {
